def _digest(seed, ticks, st):
    line = ("DIGEST seed=%d ticks=%d score=%02d alive=%d y=%04d vy=%+05d"
            " ticks_run=%d" % (seed, ticks, st["score"],
                               1 if st["alive"] else 0, st["y"], st["vy"],
                               st["ticks_run"]))
    if "shields" in st:
        line += " shields=%d" % st["shields"]
    return line


def main(argv):
    if len(argv) == 2 and argv[1] == "--selfcheck":
        return selfcheck()
    seed, ticks, flaps, powerups = _parse(argv[1:])
    every = max(1, ticks // 20)
    for t in range(ticks):
        st = run(seed, t + 1, flaps, powerups=powerups)
        if (t + 1) % every == 0:
            print(_trace(t, st))
        if not st["alive"]:
            break
    print(_digest(seed, ticks, st))

args.old_str:
def _score(pipes, vy, score):
    """Step 5: award points for pipes whose right edge is behind the bird."""
    for p in pipes:
        if not p["passed"] and p["x"] + PIPE_W <= BIRD_X:
            p["passed"] = True
            score += 1
            if abs(vy) <= GLIDE_VY:
                score += 1
    return score


def run(seed, ticks, flaps="0", powerups=False):
    """Simulate `ticks` ticks. Returns the final state dict."""
    y, vy, alive = 560, 0, True
    score, pipes, s = 0, [], seed
    ticks_run = 0
    for t in range(ticks):
        if not alive:
            break
        ticks_run = t + 1
        s, pipe = spawn(t, s)          # 1. SPAWN
        if pipe is not None:
            pipes.append(pipe)
        y, vy, alive = step_bird(y, vy, flaps[t % len(flaps)] == "1")  # 2
        scroll(pipes)                  # 3. SCROLL
        for p in pipes:                # 4. COLLIDE
            if pipe_hit(y, p):
                alive = False
                break
        if alive:                      # 5. SCORE (dead ticks score nothing)
            score = _score(pipes, vy, score)
        pipes = cull(pipes)            # 6. CULL
    state = {"y": y, "vy": vy, "score": score,
             "alive": alive, "ticks_run": ticks_run}
    return state

args.new_str:
def _score(pipes, vy, score, shields, passed_count):
    """Step 5: award points for pipes whose right edge is behind the bird."""
    for p in pipes:
        if not p["passed"] and p["x"] + PIPE_W <= BIRD_X:
            p["passed"] = True
            score += 1
            passed_count += 1
            if abs(vy) <= GLIDE_VY:
                score += 1
            if shields is not None and passed_count % 5 == 0:
                shields = min(shields + 1, 3)
    return score, shields, passed_count


def run(seed, ticks, flaps="0", powerups=False):
    """Simulate `ticks` ticks. Returns the final state dict."""
    y, vy, alive = 560, 0, True
    score, pipes, s = 0, [], seed
    shields = 1 if powerups else None
    passed_count, ticks_run = 0, 0
    for t in range(ticks):
        if not alive:
            break
        ticks_run = t + 1
        s, pipe = spawn(t, s)          # 1. SPAWN
        if pipe is not None:
            pipes.append(pipe)
        y, vy, alive = step_bird(y, vy, flaps[t % len(flaps)] == "1")  # 2
        scroll(pipes)                  # 3. SCROLL
        for p in pipes:                # 4. COLLIDE
            if pipe_hit(y, p):
                if shields is not None and shields > 0:
                    shields -= 1
                    p["passed"] = True
                else:
                    alive = False
                break
        if alive:                      # 5. SCORE (dead ticks score nothing)
            score, shields, passed_count = _score(
                pipes, vy, score, shields, passed_count)
        pipes = cull(pipes)            # 6. CULL
    state = {"y": y, "vy": vy, "score": score,
             "alive": alive, "ticks_run": ticks_run}
    if powerups:
        state["shields"] = shields
    return state

